const $=id=>document.getElementById(id);function notice(text){$('toast').textContent=text;$('toast').hidden=false;clearTimeout(window.noticeTimer);window.noticeTimer=setTimeout(()=>$('toast').hidden=true,4500);}document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id===b.dataset.view));document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x===b));}));$('themeToggle').addEventListener('click',()=>{const dark=document.documentElement.dataset.theme!=='dark';document.documentElement.dataset.theme=dark?'dark':'light';$('themeToggle').textContent=dark?'☀ Light':'☾ Dark';});$('draftState').textContent='Танилцах горим';$('globalState').textContent='Интерфэйстэй танилцаарай';$('globalProgress').textContent='Бодит үйлдлийг Chrome өргөтгөлөөс ажиллуулна.';$('description').value='БОРЛУУЛАХ БАЙР · ЖИШЭЭ ЗАР\nХан-Уул дүүрэг · 2 өрөө · 55 м²\nҮнэ: [объектын үнээ оруулна]\nДавхар, ашиглалтад орсон он: [мэдээллээ оруулна]\nУтас: [холбоо барих дугаар]';$('groups').value='https://www.facebook.com/groups/…';document.querySelectorAll('button:not([data-view]):not(#themeToggle):not([data-min])').forEach(b=>b.addEventListener('click',e=>{e.preventDefault();notice('Танилцах горим. Энэ үйлдлийг RAINY Pro Chrome өргөтгөлөөс ажиллуулна.');}));document.querySelectorAll('a').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();notice('Chrome өргөтгөлөө суулгаад ашиглаарай.');}));document.querySelectorAll('[data-min]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-min]').forEach(x=>x.classList.toggle('selected',x===b));$('interval').value=b.dataset.min;}));$('scheduleType').addEventListener('change',()=>{const once=$('scheduleType').value==='once';$('onceWrap').hidden=!once;$('intervalWrap').hidden=once;});$('deviceId').textContent='Төхөөрөмжийн код өргөтгөлд харагдана';$('licenseBadge').textContent='Танилцах горим';$('licenseDeadline').textContent='';document.querySelectorAll('input[type="file"]').forEach(x=>x.disabled=true);